 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            colored = [(rr, cc) for rr, cc in cells if grid[rr][cc] not in (0, 8)]
            if not colored:
                continue
            rmin, rmax = min(rr for rr, _ in cells), max(rr for rr, _ in cells)
            cmin, cmax = min(cc for _, cc in cells), max(cc for _, cc in cells)
            tr0, tr1 = min(rr for rr, _ in colored), max(rr for rr, _ in colored)
            tc0, tc1 = min(cc for _, cc in colored), max(cc for _, cc in colored)
            th, tw = tr1 - tr0 + 1, tc1 - tc0 + 1
            tile = [grid[tr0+i][tc0:tc1+1] for i in range(th)]
            for rr in range(rmin, rmax+1):
                for cc in range(cmin, cmax+1):
                    out[rr][cc] = tile[(rr-tr0) % th][(cc-tc0) % tw]
    return out
